import { execFile } from 'node:child_process';
import { mkdir, readFile, readdir, rm, stat, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { promisify } from 'node:util';
import { DOMAIN, SiteError, parseLabel } from './sites.js';

const run = promisify(execFile);

// First line of every generated file: the settings it was made from, so it can be edited again
const META = /^# wmw-managed (\{.*\})$/m;

// Names that are not in the nginx files but must never become an app
const ALWAYS_BLOCKED = ['www', 'backoffice', 'admin', 'mail'];

const SCHEMES = ['http', 'https'];

/** Commands that test and reload nginx. The agent runs as a user with passwordless sudo. */
export function systemNginx() {
  const exec = (cmd, args) => run('sudo', ['-n', cmd, ...args], { timeout: 20000 });
  return {
    validate: () => exec('nginx', ['-t']),
    reload: () => exec('systemctl', ['reload', 'nginx'])
  };
}

/** Only these settings can be set from the UI; nothing is ever copied into the config as free text */
export function parseSettings(input, { blockedPorts = [] } = {}) {
  const port = Number(input?.port);
  if (!Number.isInteger(port) || port < 1024 || port > 65535) {
    throw new SiteError(422, 'The port must be a whole number from 1024 to 65535.');
  }
  if (blockedPorts.includes(port)) throw new SiteError(422, `Port ${port} cannot be used.`);

  const scheme = input?.scheme ?? 'http';
  if (!SCHEMES.includes(scheme)) throw new SiteError(422, 'The upstream must use http or https.');

  const maxBodyMb = Number(input?.maxBodyMb ?? 50);
  if (!Number.isInteger(maxBodyMb) || maxBodyMb < 1 || maxBodyMb > 1024) {
    throw new SiteError(422, 'The upload limit must be from 1 to 1024 MB.');
  }

  return {
    port,
    scheme,
    websocket: input?.websocket === true,
    streaming: input?.streaming === true,
    maxBodyMb
  };
}

/** The server block of an app that is proxied to a local port */
export function renderApp(name, settings, { domain = DOMAIN, certDir = `/etc/letsencrypt/live/${domain}`, logDir = `/var/log/nginx/${domain}` } = {}) {
  const host = `${name}.${domain}`;
  const { port, scheme, websocket, streaming, maxBodyMb } = settings;
  const meta = JSON.stringify({ v: 1, kind: 'proxy', ...settings });

  const location = [
    'expires $expires;',
    '',
    'proxy_redirect                      off;',
    'proxy_set_header Host               $host;',
    'proxy_set_header X-Real-IP          $remote_addr;',
    'proxy_set_header X-Forwarded-For    $proxy_add_x_forwarded_for;',
    'proxy_set_header X-Forwarded-Proto  $scheme;',
    `proxy_read_timeout                  ${streaming ? '3600' : '1m'};`,
    'proxy_connect_timeout               1m;',
    ...(streaming ? ['proxy_send_timeout                  3600;', 'proxy_buffering                     off;', 'proxy_cache                         off;', 'chunked_transfer_encoding          off;'] : []),
    '',
    `proxy_pass                          ${scheme}://127.0.0.1:${port};`,
    ...(websocket
      ? ['', 'proxy_http_version 1.1;', 'proxy_set_header Upgrade $http_upgrade;', 'proxy_set_header Connection "upgrade";']
      : [])
  ];

  return `# wmw-managed ${meta}
# Generated by the site agent. Change it in the BackOffice (Sites > Apps): manual edits are overwritten.
server {
    listen 443 ssl;
    listen [::]:443 ssl;
    http2 on;

    server_name ${host};

    client_max_body_size ${maxBodyMb}m;
    charset utf-8;

    ssl_certificate ${certDir}/fullchain.pem;
    ssl_certificate_key ${certDir}/privkey.pem;

    error_log  ${logDir}/${name}-error.log;
    access_log ${logDir}/${name}-access.log;

    # Gzip
    include /etc/nginx/includes/gzip.conf;

    location / {
${location.map((line) => (line ? `        ${line}` : '')).join('\n')}
    }
}
`;
}

/** Server blocks of a config file: their names and first proxy_pass. Comments are ignored. */
export function parseServerBlocks(text) {
  const code = text.replace(/^\s*#.*$/gm, '').replace(/\s#.*$/gm, '');
  const blocks = [];
  const start = /(^|[;}\s])server\s*\{/g;
  let match;
  while ((match = start.exec(code))) {
    let depth = 1;
    let i = start.lastIndex;
    while (i < code.length && depth > 0) {
      if (code[i] === '{') depth += 1;
      else if (code[i] === '}') depth -= 1;
      i += 1;
    }
    const body = code.slice(start.lastIndex, i - 1);
    const names = [...body.matchAll(/(^|[;{}\s])server_name\s+([^;]+);/g)].flatMap((m) => m[2].trim().split(/\s+/));
    blocks.push({ names, upstream: /proxy_pass\s+(\S+?);/.exec(body)?.[1] ?? null });
    start.lastIndex = i;
  }
  return blocks;
}

export function createNginxManager({
  managedDir,
  mainFile,
  domain = DOMAIN,
  blockedPorts = [],
  validate,
  reload,
  renderOptions = {}
}) {
  let queue = Promise.resolve();
  // Config changes run one at a time: each one is tested and reloaded before the next starts
  const serial = (task) => {
    const result = queue.then(task, task);
    queue = result.catch(() => {});
    return result;
  };

  const parseName = (input) => parseLabel(input, domain);
  const fileOf = (name) => path.join(managedDir, `${name}.conf`);
  const suffix = `.${domain}`;

  const read = (file) => readFile(file, 'utf8').catch((error) => (error.code === 'ENOENT' ? null : Promise.reject(error)));

  async function managed() {
    let entries = [];
    try {
      entries = await readdir(managedDir);
    } catch (error) {
      if (error.code !== 'ENOENT') throw error;
    }
    const apps = [];
    for (const file of entries.filter((entry) => entry.endsWith('.conf')).sort()) {
      const name = file.slice(0, -'.conf'.length);
      const text = await read(path.join(managedDir, file));
      let settings = null;
      try {
        settings = META.test(text) ? parseSettings(JSON.parse(META.exec(text)[1])) : null;
      } catch {
        settings = null;
      }
      const updatedAt = (await stat(path.join(managedDir, file))).mtime.toISOString();
      const blocks = parseServerBlocks(text);
      apps.push({ name, host: `${name}${suffix}`, kind: settings ? 'proxy' : 'system', updatedAt, ...(settings ?? { upstream: blocks[0]?.upstream ?? null }) });
    }
    return apps;
  }

  /** Subdomains that the main nginx file serves with its own block (read only) */
  async function system() {
    const text = (await read(mainFile)) ?? '';
    const seen = new Map();
    for (const block of parseServerBlocks(text)) {
      for (const host of block.names) {
        if (!host.endsWith(suffix) || host.startsWith('*')) continue;
        const name = host.slice(0, -suffix.length);
        if (!seen.has(name)) seen.set(name, { name, host, kind: 'system', upstream: block.upstream });
      }
    }
    return [...seen.values()];
  }

  async function list() {
    const mine = await managed();
    const taken = new Set(mine.map((app) => app.name));
    const apps = [...mine, ...(await system()).filter((app) => !taken.has(app.name))];
    return apps.sort((a, b) => a.name.localeCompare(b.name));
  }

  /** Every name nginx already answers for: a static folder or a new app must not reuse one */
  async function definedNames() {
    return new Set((await list()).map((app) => app.name));
  }

  /** Write, test and reload; put things back if nginx refuses */
  async function apply(name, content) {
    const file = fileOf(name);
    const previous = await read(file);
    const restore = () => (previous === null ? rm(file, { force: true }) : writeFile(file, previous));

    await mkdir(managedDir, { recursive: true });
    if (content === null) await rm(file, { force: true });
    else await writeFile(file, content, { mode: 0o644 });

    try {
      await validate();
    } catch (error) {
      await restore();
      const detail = String(error.stderr ?? error.message).split('\n').filter((line) => /\[emerg\]|\[crit\]/.test(line)).join(' ').slice(0, 300);
      throw new SiteError(422, `nginx rejected the configuration${detail ? `: ${detail}` : '.'} Nothing was changed.`);
    }
    try {
      await reload();
    } catch {
      await restore();
      await validate().then(reload).catch(() => {});
      throw new SiteError(500, 'nginx could not be reloaded. The change was undone.');
    }
  }

  async function find(name) {
    return (await managed()).find((app) => app.name === name);
  }

  function create(input) {
    return serial(async () => {
      const name = parseName(input?.name);
      const settings = parseSettings(input, { blockedPorts });
      if (ALWAYS_BLOCKED.includes(name) || (await definedNames()).has(name)) {
        throw new SiteError(409, `${name}${suffix} is already used.`);
      }
      await apply(name, renderApp(name, settings, { domain, ...renderOptions }));
      return find(name);
    });
  }

  function update(input, changes) {
    return serial(async () => {
      const name = parseName(input);
      const current = await find(name);
      if (!current) throw new SiteError(404, `${name}${suffix} is not an app managed here.`);
      if (current.kind !== 'proxy') throw new SiteError(403, `${name}${suffix} is not managed here.`);
      const settings = parseSettings({ ...current, ...changes }, { blockedPorts });
      await apply(name, renderApp(name, settings, { domain, ...renderOptions }));
      return find(name);
    });
  }

  /** The file is kept in `.trash` so a mistake can be undone by hand */
  function remove(input) {
    return serial(async () => {
      const name = parseName(input);
      const current = await find(name);
      if (!current) {
        const isSystem = (await system()).some((app) => app.name === name);
        throw isSystem
          ? new SiteError(403, `${name}${suffix} is defined in the main nginx file and cannot be removed here.`)
          : new SiteError(404, `${name}${suffix} does not exist.`);
      }
      const trash = path.join(managedDir, '.trash');
      await mkdir(trash, { recursive: true });
      const stamp = new Date().toISOString().replace(/[:.]/g, '-');
      const backup = path.join(trash, `${name}-${stamp}.conf.bak`);
      await writeFile(backup, (await read(fileOf(name))) ?? '');
      try {
        await apply(name, null);
      } catch (error) {
        await rm(backup, { force: true });
        throw error;
      }
    });
  }

  return { list, definedNames, create, update, remove };
}
